head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF40802.xml";
scwin.params = new Array();
scwin.vAnufeeNotiImpostNo;
scwin.LD_MKT_TP_CD = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    var url = "/YearAssessmentFeeManagement.do?method=readYearAssessmentFeeByDelistDD&inputMessageId=YEAR_ASSESSMENT_FEE_READ_INOUT&outputMessageId=YEAR_ASSESSMENT_FEE_READ_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISUR_CD=" + scwin.params[0];
    url += "&BAS_YY=" + scwin.params[1];
    url += "&MKT_ID=" + scwin.params[2];
    url += "&ANULFEE_NOTI_IMPOST_NO=" + scwin.params[3];
    dts_yearAssessmentFee.DataID = encodeURI(url);
    dts_yearAssessmentFee.reset();
    scwin.fn_setInitial_isur_cd();
};
scwin.fn_setInitial_isur_cd = function() {
    $c.stf.setObjectValue(txb_SEARCH_ISUR_CD, dts_yearAssessmentFee.getCellData(1, "ISUR_CD"));
    $c.stf.setObjectValue(txb_SEARCH_COM_NM, dts_yearAssessmentFee.getCellData(1, "COM_NM"));
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_ZIPCD.setValue(arrPar[0]);
    txb_ADDR.setValue(arrPar[1]);
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_SEARCH_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_AVG_MKTCAP) == "") {
        $c.win.alert("계산버튼을 클릭하여 [시가총액]을 입력해 주세요.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_STKCERT_ANULFEE) == "") {
        $c.win.alert("계산버튼을 클릭하여 [수시연부과금액]을 입력해 주세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_ADDR) == "") {
        $c.win.alert("[주소]를 입력해 주세오.");
        txb_ADDR.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        scwin.vAnufeeNotiImpostNo = scwin.fn_gettNewNotiImpostNo();
        dts_yearAssessmentFee.setCellData(1, "ANULFEE_NOTI_IMPOST_NO", scwin.vAnufeeNotiImpostNo);
        dts_yearAssessmentFee.setCellData(1, "LD_MKT_TP_CD", scwin.LD_MKT_TP_CD);
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_gettNewNotiImpostNo = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=YEAR_ASSESSMENT_FEE_READ_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.yafmgt.readYearAssessmentFeeNotiImpostNoByDelistDD" + "&{P}param01=" + $c.stf.getObjectValue(edt_DelistDD).substring(0, 4) + "&{P}param02=" + scwin.LD_MKT_TP_CD;
    dts_NotiImpostNo.DataID = encodeURI(url);
    dts_NotiImpostNo.reset();
    return dts_NotiImpostNo.getCellData(1, "ANULFEE_NOTI_IMPOST_NO");
};
scwin.fn_update = function() {
    TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        var rtn = confirm('내용을 수정 하시겠습니까?');
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            scwin.fn_trs(TR_JOB_UPDATE);
        }
    }
};
scwin.fn_delete = function() {
    TR_JOB = 'R';
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) {
        // [확인] 버튼이 눌려졌을 경우
        scwin.fn_trs(TR_JOB_DELETE);
    }
};
scwin.fn_trs = function(trsIdx) {
    if (TR_JOB == "I") {
        var vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
        trs_Insert.Action = "/YearAssessmentFeeManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveUnScheduleAnulFee&MKT_ID=" + scwin.LD_MKT_TP_CD;
        trs_Insert.KeyName = "toinb_dataid4";
        trs_Insert.KeyValue = "JSP(I:pInput=dts_yearAssessmentFee)";
        trs_Insert.Post();
    } else if (TR_JOB == "U") {
        var vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        trs_Update.Action = "/YearAssessmentFeeManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateUnScheduleAnulFee&MKT_ID=" + scwin.LD_MKT_TP_CD;
        trs_Update.KeyName = "toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput=dts_yearAssessmentFee)";
        trs_Update.Post();
    } else if (TR_JOB == "R") {
        var vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
        trs_Delete.Action = "/YearAssessmentFeeManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=deleteUnScheduleAnulFee";
        trs_Delete.KeyName = "toinb_dataid4";
        trs_Delete.KeyValue = "JSP(I:pInput=dts_yearAssessmentFee)";
        trs_Delete.Post();
    }
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수시연부과금 수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수시연부과금 수정"));
};
scwin.trs_Insert_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수시연부과금 입력"));
    await $c.frame.CloseFrame();
};
scwin.trs_Insert_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수시연부과금 입력"));
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수시연부과금 삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수시연부과금 삭제"));
};
scwin.btn_search_onclick = function() {
    $c.lc.fn_PopFindZipCd();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_yearAssessmentFee_OnLoadError = function() {
    $c.stf.alert_error(dts_yearAssessmentFee);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    getId = $c.frame.path("../").fn_getId;
    scwin.params = getId();
    scwin.vAnufeeNotiImpostNo = scwin.params[3];
    if (scwin.vAnufeeNotiImpostNo != null) {
        $c.stf.showObj(btn_save, false);
        $c.stf.showObj(panel_modify, true);
    } else {
        $c.stf.showObj(btn_save, true);
        $c.stf.showObj(panel_modify, false);
    }
    scwin.fn_read();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_DelistDD);
};
scwin.btn_SDate1_onclick = function() {
    popUpCalendar2(edt_DelistDecisionDD);
};
scwin.btn_calculate_onclick = function() {
    var isurCd = $c.stf.getObjectValue(txb_SEARCH_ISUR_CD);
    var deListDD = $c.stf.getObjectValue(edt_DelistDD);
    var deListDecisionDD = $c.stf.getObjectValue(edt_DelistDecisionDD);
    if (isurCd == "") {
        $c.win.alert('회사를 선택해 주세요');
        return;
    }
    if (deListDecisionDD == "") {
        $c.win.alert('상장폐지 결정일을 입력해 주세요');
        return;
    }
    if (deListDD == "") {
        $c.win.alert('상장폐지 전일을 입력해 주세요');
        return;
    }
    if (deListDecisionDD >= deListDD) {
        $c.win.alert('상장폐지결정일은 상장폐지전일보다\n이전 날짜로 입력해 주세요');
        return;
    }
    var queryId = "";
    if (scwin.LD_MKT_TP_CD == '1') {
        queryId = "lds.stf.lstmgt.yafmgt.yuga.calcuYearAssessmentFeeByDelistDD";
    } else if (scwin.LD_MKT_TP_CD == '2') {
        queryId = "lds.stf.lstmgt.yafmgt.kosdaq.calcuYearAssessmentFeeByDelistDD";
    } else {
        queryId = "lds.stf.lstmgt.yafmgt.yuga.calcuYearAssessmentFeeByDelistDD";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName&outputMessageId=YEAR_ASSESSMENT_FEE_READ_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}DELIST_DD=" + deListDD + "&{P}DELIST_DECISION_DD=" + deListDecisionDD + "&{P}ISUR_CD=" + isurCd;
    dts_yearAssessmentFee.DataID = encodeURI(url);
    dts_yearAssessmentFee.reset();
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_modify_onclick = function() {
    scwin.fn_update();
};
scwin.img_com_nm_onclick = function() {
    $c.cm.IsurcdSearch(txb_SEARCH_ISUR_CD, txb_SEARCH_COM_NM);
};
scwin.dts_yearAssessmentFee_OnLoadCompleted = function(rowcount) {
    if (rowcount == 0) {
        $c.win.alert('일평균시가총액이 존재하지 않습니다.');
    }
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
